arguments.prompt:
You are implementing a Blazor Web App for a logistics company that tracks shipments. The project has already been scaffolded at:
- Server project: /tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker/
- Client project: /tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker.Client/

The project uses Interactive Auto, Global mode with Individual authentication (ASP.NET Core Identity, SQLite).

## What to implement

### 1. Remove template defaults
Delete these files from the Client project's Pages folder:
- Counter.razor
- Weather.razor

Keep Home.razor but rewrite it as a landing page for the shipment tracker.
Keep Auth.razor and NotFound.razor as-is.

### 2. Shared model (in Client project since it needs to be accessible from both)

Create `/tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 3. Service interface (in Client project)

Create `/tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Client-side implementation (HttpClient-based, in Client project)

Create `/tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker.Client/Services/ShipmentServiceClient.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentServiceClient(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{trackingNumber}");
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        return await http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(customerEmail)}") ?? [];
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        await http.PutAsJsonAsync($"api/shipments/{id}/status", status);
    }
}
```

### 5. Register HttpClient and service in Client Program.cs

Edit `/tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker.Client/Program.cs` to:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddHttpClient("ShipmentTracker.ServerAPI", client =>
    client.BaseAddress = new Uri(builder.HostEnvironment.BaseAddress));
builder.Services.AddScoped(sp => sp.GetRequiredService<IHttpClientFactory>().CreateClient("ShipmentTracker.ServerAPI"));
builder.Services.AddScoped<IShipmentService, ShipmentServiceClient>();

await builder.Build().RunAsync();
```

### 6. Server-side implementation (seed data, in server project)

Create `/tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker/Services/ShipmentServiceServer.cs`:
```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServiceServer : IShipmentService
{
    private static readonly List<Shipment> _shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-001234", Origin = "New York, USA", Destination = "London, UK", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "alice@example.com" },
        new() { Id = 2, TrackingNumber = "TRK-001235", Origin = "Shanghai, China", Destination = "Los Angeles, USA", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(1), CustomerEmail = "bob@example.com" },
        new() { Id = 3, TrackingNumber = "TRK-001236", Origin = "Berlin, Germany", Destination = "Tokyo, Japan", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(7), CustomerEmail = "charlie@example.com" },
        new() { Id = 4, TrackingNumber = "TRK-001237", Origin = "Sydney, Australia", Destination = "Dubai, UAE", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-14), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "alice@example.com" },
        new() { Id = 5, TrackingNumber = "TRK-001238", Origin = "São Paulo, Brazil", Destination = "Paris, France", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "bob@example.com" },
    ];

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(_shipments.ToList());
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = _shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        var shipments = _shipments.Where(s => s.CustomerEmail.Equals(customerEmail, StringComparison.OrdinalIgnoreCase)).ToList();
        return Task.FromResult(shipments);
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id);
        if (shipment != null)
        {
            shipment.Status = status;
        }
        return Task.CompletedTask;
    }
}
```

### 7. API endpoints and server DI registration

Edit the server's Program.cs to add the service registration and API endpoints. Add BEFORE `var app = builder.Build();`:
```csharp
builder.Services.AddScoped<IShipmentService, ShipmentServiceServer>();
```

Add the required `using` at the top:
```csharp
using ShipmentTracker.Client.Services;
using ShipmentTracker.Services;
using ShipmentTracker.Client.Models;
```

Add AFTER `app.MapAdditionalIdentityEndpoints();` and BEFORE `app.Run();`:
```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments").RequireAuthorization();

shipments.MapGet("/", async (IShipmentService service) =>
    await service.GetAllShipmentsAsync());

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

shipments.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
    await service.GetShipmentsByCustomerAsync(email));

shipments.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
{
    await service.UpdateShipmentStatusAsync(id, status);
    return Results.NoContent();
});
```

### 8. Pages in Client project

**Rewrite Home.razor** (`/tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker.Client/Pages/Home.razor`):
```razor
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>
<p>Welcome to the logistics shipment tracking system.</p>

<AuthorizeView>
    <Authorized>
        <p>You are signed in as <strong>@context.User.Identity?.Name</strong>.</p>
        <ul>
            <li><a href="shipments">View All Shipments (Dispatchers)</a></li>
            <li><a href="track">Track My Shipment</a></li>
        </ul>
    </Authorized>
    <NotAuthorized>
        <p>Please <a href="Account/Login">sign in</a> to track shipments or view dispatch information.</p>
    </NotAuthorized>
</AuthorizeView>
```

**Create Dispatcher page** at `/tmp/sv-ef500695b1e6440a934dab6536027696/ShipmentTracker/ShipmentTracker.Client/Pages/Shipments.razor`:
```razor
@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>All Shipments</PageTitle>

<h1>Shipments</h1>

<div>
    <label>
        Filter by status:
        <select @bind="selectedStatus">
            <option value="">All</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </label>
    <label>
        Search destination:
        <input type="text" @bind="searchDestination" @bind:event="oninput" placeholder="Type to filter..." />
    </label>
</div>

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else
{
    <table>
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
