@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>All Shipments</PageTitle>

<h1>Shipments</h1>

<div>
    <label>
        Filter by status:
        <select @bind="selectedStatus">
            <option value="">All</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </label>
    <label>
        Search destination:
        <input type="text" @bind="searchDestination" @bind:event="oninput" placeholder="Type to filter..." />
    </label>
</div>

@if (shipments is null)
{
    <p>Loading shipments...</p>
}
else
{
    <table>
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td>@shipment.Status</td>
                    <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select @bind="shipment.Status" @bind:after="() => OnStatusChanged(shipment)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private string selectedStatus = "";
    private string searchDestination = "";

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrEmpty(selectedStatus) || s.Status.ToString() == selectedStatus)
            .Where(s => string.IsNullOrEmpty(searchDestination) || s.Destination.Contains(searchDestination, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task OnStatusChanged(Shipment shipment)
    {
        await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, shipment.Status);
    }
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div>
    <label>
        Enter tracking number:
        <input type="text" @bind="trackingNumber" placeholder="e.g. TRK-001234" />
    </label>
    <button @onclick="SearchShipment">Track</button>
</div>

@if (searched && shipment is null)
{
    <p><strong>No shipment found with tracking number "@trackingNumber".</strong></p>
}
else if (shipment is not null)
{
    <div>
        <h2>Shipment Details</h2>
        <dl>
            <dt>Tracking Number</dt>
            <dd>@shipment.TrackingNumber</dd>

            <dt>Origin</dt>
            <dd>@shipment.Origin</dd>

            <dt>Destination</dt>
            <dd>@shipment.Destination</dd>

            <dt>Status</dt>
            <dd><strong>@shipment.Status</strong></dd>

            <dt>Shipped Date</dt>
            <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

            <dt>Estimated Delivery</dt>
            <dd>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
        </dl>

        @if (shipment.Status == ShipmentStatus.Delivered)
        {
            <p>✅ Your shipment has been delivered!</p>
        }
        else if (shipment.Status == ShipmentStatus.Delayed)
        {
            <p>⚠️ Your shipment is delayed. Updated delivery estimate shown above.</p>
        }
        else
        {
            <p>📦 Your shipment is on its way.</p>
        }
    </div>
}

@code {
    private string trackingNumber = "";
    private Shipment? shipment;
    private bool searched;

    private async Task SearchShipment()
    {
        searched = true;
        shipment = null;
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        }
    }
}

