</div>

@if (searched && shipment is null)
{
    <p><strong>No shipment found with tracking number "@trackingNumber".</strong></p>
}
else if (shipment is not null)
{
    <div>
        <h2>Shipment Details</h2>
        <dl>
            <dt>Tracking Number</dt>
            <dd>@shipment.TrackingNumber</dd>

            <dt>Origin</dt>
            <dd>@shipment.Origin</dd>

            <dt>Destination</dt>
            <dd>@shipment.Destination</dd>

            <dt>Status</dt>
            <dd><strong>@shipment.Status</strong></dd>

            <dt>Shipped Date</dt>
            <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

            <dt>Estimated Delivery</dt>
            <dd>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
        </dl>

        @if (shipment.Status == ShipmentStatus.Delivered)
        {
            <p>✅ Your shipment has been delivered!</p>
        }
        else if (shipment.Status == ShipmentStatus.Delayed)
        {
            <p>⚠️ Your shipment is delayed. Updated delivery estimate shown above.</p>
        }
        else
        {
            <p>📦 Your shipment is on its way.</p>
        }
    </div>
}

@code {
    private string trackingNumber = "";
    private Shipment? shipment;
    private bool searched;

    private async Task SearchShipment()
    {
        searched = true;
        shipment = null;
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        }
    }
}
```

